const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const state={method:'phone',country:COUNTRIES.find(c=>c.iso===(localStorage.getItem('nh-country')||'US')),language:localStorage.getItem('nh-language')||'en',busy:false,scenario:'timeout',timer:null};
if(!state.country)state.country=COUNTRIES.find(c=>c.iso==='US');
const dialog=$('#country-dialog');
function updateCountry(){const c=state.country;$('#country-flag').src=`flags/${c.iso}.png`;$('#country-code').textContent=c.code;$('#country-open').setAttribute('aria-label',`Country code: ${c.name} ${c.code}`)}
function filteredCountries(q){q=q.trim().toLocaleLowerCase();return COUNTRIES.filter(c=>c.name.toLocaleLowerCase().includes(q)||c.code.includes(q)||c.iso.toLowerCase()===q)}
function renderCountries(){const query=$('#country-search').value,rows=filteredCountries(query);$('#search-clear').hidden=!query;$('#result-count').textContent=`${rows.length} countries`;$('#country-list').replaceChildren();for(const c of rows){const b=document.createElement('button');b.className='country-row';b.type='button';b.setAttribute('role','radio');b.setAttribute('aria-checked',String(c.iso===state.country.iso));b.dataset.iso=c.iso;const img=new Image();img.src=`flags/${c.iso}.png`;img.alt='';const name=document.createElement('span');name.className='name';name.textContent=c.name;const code=document.createElement('span');code.className='code';code.textContent=c.code;const radio=document.createElement('span');radio.className='radio';radio.setAttribute('aria-hidden','true');radio.textContent=c.iso===state.country.iso?'✓':'';b.append(img,name,code,radio);b.onclick=()=>{state.country=c;localStorage.setItem('nh-country',c.iso);updateCountry();dialog.close();};$('#country-list').append(b)}if(!rows.length){const p=document.createElement('p');p.className='empty';p.textContent='No countries found';$('#country-list').append(p)}}
$('#country-open').onclick=()=>{if(state.busy)return;$('#country-search').value='';renderCountries();dialog.showModal();$('#country-search').focus()};
$('#country-search').oninput=renderCountries;$('#search-clear').onclick=()=>{$('#country-search').value='';renderCountries();$('#country-search').focus()};$('#country-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>$('#country-open').focus());
$('#country-list').onkeydown=e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const rows=all('.country-row'),i=rows.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?rows.length-1:(i+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows[n].focus()};
function setBusy(b,google=false){state.busy=b;$('#submit').classList.toggle('loading',b&&!google);$('#submit').setAttribute('aria-busy',String(b&&!google));for(const n of all('#auth-form button,#auth-form input,#google'))n.disabled=b;$('#submit').disabled=b||state.scenario==='offline';$('#google').disabled=b||state.scenario==='offline';$('#processing-status').textContent=b&&!google?'Sending code…':'';$('#google').classList.toggle('loading',b&&google);$('#google').setAttribute('aria-busy',String(b&&google));$('#google span').classList.toggle('dots',b&&google);if(google&&b){$('#google').setAttribute('aria-label','Continue with Google');$('#google span').innerHTML='<i></i><i></i><i></i>';}else if(!b)$('#google span').textContent='Continue with Google';}
function message(s){$('#status').textContent=s;$('#status').hidden=!s;}
function restore(s,timeout=false){clearTimeout(state.timer);setBusy(false);message(s);$('#submit .button-label').firstChild.textContent=timeout?'Try again ':'Send code ';$('#google span').textContent='Continue with Google';$('#google').removeAttribute('aria-label');}
for(const b of all('[data-method]'))b.onclick=()=>{if(state.busy)return;state.method=b.dataset.method;for(const t of all('[data-method]'))t.setAttribute('aria-selected',String(t===b));$('#phone-group').hidden=state.method!=='phone';$('#email-group').hidden=state.method!=='email';scenario(state.scenario);};
$('#auth-form').onsubmit=e=>{e.preventDefault();if(state.busy||state.scenario==='offline')return;const value=$(state.method==='phone'?'#phone-input':'#email-input').value.trim();const valid=state.method==='phone'?/^\+?[\d\s().-]{6,22}$/.test(value)&&value.replace(/\D/g,'').length>=6:/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);$('#validation').textContent=state.method==='phone'?'Enter a valid phone number.':'Enter a valid email address.';$('#validation').hidden=valid;if(!valid){$(state.method==='phone'?'#phone-input':'#email-input').focus();return}message('');setBusy(true);state.timer=setTimeout(()=>restore(state.scenario==='error'?'Something went wrong, please try again':'This is taking longer than expected. Please try again.',state.scenario!=='error'),state.scenario==='error'?2000:10000);};
$('#google').onclick=()=>{if(state.busy||state.scenario==='offline')return;message('');setBusy(true,true);state.timer=setTimeout(()=>{restore('Something went wrong, please try again');$('#google span').textContent='Try again';$('#google').setAttribute('aria-busy','false');},2000)};
function scenario(s){clearTimeout(state.timer);state.scenario=s;setBusy(false);$('#validation').hidden=true;$('#submit .button-label').firstChild.textContent='Send code ';message(s==='offline'?'Connect to the internet to continue':s==='expired'?'Please log in again':'');if(s==='offline'){const retry=document.createElement('button');retry.textContent='Try again';retry.type='button';retry.onclick=()=>{if(navigator.onLine){$('#scenario').value='timeout';scenario('timeout')}};$('#status').append(retry)}}
$('#scenario').onchange=e=>scenario(e.target.value);window.addEventListener('offline',()=>scenario('offline'));window.addEventListener('pagehide',()=>clearTimeout(state.timer));
const langs=[['en','English','English','GB'],['hi','Hindi','हिंदी','IN'],['ar','Arabic','العربية','SA'],['ur','Urdu','اردو','PK']];
function renderLanguages(){const box=$('#languages');box.setAttribute('role','radiogroup');box.setAttribute('aria-label','Language');box.replaceChildren();for(const [id,name,native,flag]of langs){const b=document.createElement('button');b.className='language-row';b.setAttribute('role','radio');b.setAttribute('aria-checked',String(state.language===id));b.innerHTML=`<img src="flags/${flag}.png" alt=""><span>${name}<small lang="${id}" dir="auto">${native}</small></span>${state.language===id?'<i class="language-check" aria-hidden="true">✓</i>':''}`;b.onclick=()=>{state.language=id;localStorage.setItem('nh-language',id);renderLanguages()};box.append(b)}}
$('#language-continue').onclick=()=>{const b=$('#language-continue');if(b.disabled)return;b.disabled=true;b.classList.add('loading');b.innerHTML='<span class="dots" aria-hidden="true"><i></i><i></i><i></i></span>';setTimeout(()=>{location.href='https://www.figma.com/proto/MR9935oQZACMjndzGIUgq5/NoorHeroes-APP?page-id=928%3A2&node-id=1215-34'},1800)};
for(const b of all('[data-view]'))b.onclick=()=>{clearTimeout(state.timer);setBusy(false);$('#login').hidden=b.dataset.view!=='login';$('#language').hidden=b.dataset.view!=='language'};
updateCountry();renderLanguages();if(!navigator.onLine)scenario('offline');
window.NHReview={state,filteredCountries,scenario};
$('#text-scale').onchange=e=>{document.documentElement.style.fontSize=e.target.value+'px';document.documentElement.dataset.scale=e.target.value;};
$('#direction').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));document.body.dir=on?'rtl':'ltr';};
$('#reduce-motion').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));document.documentElement.dataset.motion=on?'reduced':'full';};
